// PRIVATE original scenarios. Sources are technical references, not company question banks.
// Grade rubrics describe evidence for the requested action, not years or people management.
const grades = ['Intern', 'Junior', 'Middle', 'Senior', 'Lead'];
const rows = [];
const practicalText = new Set(['ram-budget', 'brownout-probe', 'stack-snapshot', 'i2c-rise', 'spi-mode', 'uart-budget', 'pwm-divider', 'priority-inversion', 'deadline-budget', 'queue-capacity', 'power-loss-record', 'flash-wear', 'reset-cause', 'hil-faults']);
// The same skill can recur in independent families; unrelated "verification" actions stay separate.
const skillKeys = {
  'spsc-ring': { bounds: 'queue-bounds' }, 'timer-wrap': { bounds: 'time-range' },
  'power-loss-record': { recovery: 'persistent-recovery', verification: 'power-loss-validation' },
  'boot-rollback': { recovery: 'firmware-recovery' },
  'signature-not-crc': { verification: 'image-authenticity' },
  'bounded-fault-log': { verification: 'snapshot-validation' },
  'sensor-safe-state': { verification: 'safe-recovery-validation' },
  'reset-cause': { diagnosis: 'fault-localization' },
  'firmware-provenance': { diagnosis: 'symbolization' },
  'watchdog-progress': { diagnosis: 'watchdog-validation' },
};
const R = (meets, strong) => ({ meets, strong });
const L = (task, expected, ...anchors) => ({ task, expected, anchors });
function F(group, slug, title, prompt, code, sources, skills, levels, alternatives, errors) {
  const byGrade = Object.fromEntries(grades.map((grade, index) => {
    const level = levels[index];
    return [grade, { task: level.task, expected: level.expected,
      criteria: level.anchors.map((anchor, position) => ({
        id: `criterion-${position + 1}`,
        skillId: `Embedded:${group}:${skillKeys[slug]?.[skills[position][0]] || skills[position][0]}`,
        label: skills[position][1],
        missing: `Отсутствует свидетельство по критерию «${skills[position][1]}» в заданном объёме уровня ${grade}.`,
        partial: `Есть относящееся к задаче действие, но не выполнен проверяемый результат: ${anchor.meets}`,
        meets: anchor.meets, strong: anchor.strong,
      })),
    }];
  }));
  rows.push({ id: `open-embedded-${slug}`, specialization: 'Embedded', group, title, prompt,
    answerFormat: code ? 'code' : 'text', language: code ? 'text' : null, practical: code || practicalText.has(slug),
    sourceIds: sources.map(source => `embedded-${source}`), tags: [slug, group.toLowerCase(), code ? 'pseudocode' : 'reasoning'],
    referenceAnswer: byGrade.Middle.criteria.map(criterion => criterion.meets).join(' '),
    acceptableAlternatives: alternatives, criticalErrors: errors, criteria: byGrade.Middle.criteria, levels: byGrade,
    personalization: { allowed: ['domain', 'entityNames', 'projectContext'], invariants: [
      'Сохранять электрические ограничения, числа, единицы, модель памяти и последовательность событий.',
      'Не менять объём действий выбранного грейда, критерии и критические ошибки.',
      'Описание опыта меняет контекст устройства, но не считается ответом или доказательством компетенции.',
    ] },
  });
}

